    private static HashSet<int> CommercialParseGroups(string text){var values=text.Split([',',';',' '],StringSplitOptions.RemoveEmptyEntries).Select(s=>int.Parse(s,CultureInfo.InvariantCulture)).ToHashSet();if(values.Count>1000||values.Any(n=>n<=0||n>16777215))throw new IOException("Use positive comma-separated talkgroup IDs (maximum 1000).");return values;}
    private CapCarrier[] ValidateDmrTrunkMaps(IEnumerable<TrunkMapRow> rows){var maps=rows.Where(r=>r.FrequencyMHz.Trim().Length>0).Select(r=>new CapCarrier(r.Lcn,CommercialParseMHz(r.FrequencyMHz),r.Confirmed,r.Evidence,r.ColorCode)).ToArray();TrunkFollower.Validate(new("test","test",dmrTrunkMode.SelectedItem?.ToString()=="P25 Phase I"?"P25":dmrTrunkMode.SelectedItem?.ToString()??"Capacity Plus",1,maps));return maps;}
    private static long CommercialParseMHz(string text){if(!decimal.TryParse(text,NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out var mhz)||mhz<=0||mhz>6000||mhz*1000000!=decimal.Truncate(mhz*1000000))throw new IOException("Enter MHz with at most six decimal places.");return(long)(mhz*1000000);}
    private CapCarrier[] ReadDmrTrunkMaps(){if(!dmrTrunkMapGrid.CommitEdit(DataGridEditingUnit.Cell,true)||!dmrTrunkMapGrid.CommitEdit(DataGridEditingUnit.Row,true))throw new IOException("Fix the highlighted map cell.");return ValidateDmrTrunkMaps(dmrTrunkMaps);}
    private TrunkProfile ReadDmrTrunkProfile()=>new(dmrTrunkId,dmrTrunkName.Text.Trim(),dmrTrunkMode.SelectedItem?.ToString()=="P25 Phase I"?"P25":dmrTrunkMode.SelectedItem?.ToString()??"Capacity Plus",CommercialParseMHz(dmrTrunkControl.Text),ReadDmrTrunkMaps(),string.IsNullOrWhiteSpace(dmrTrunkNetwork.Text)?null:int.Parse(dmrTrunkNetwork.Text,CultureInfo.InvariantCulture),string.IsNullOrWhiteSpace(dmrTrunkSite.Text)?null:int.Parse(dmrTrunkSite.Text,CultureInfo.InvariantCulture));
    private void ApplyDmrTrunkRules(){var allow=CommercialParseGroups(dmrTrunkAllow.Text);var ignore=CommercialParseGroups(dmrTrunkIgnore.Text);int? hold=string.IsNullOrWhiteSpace(dmrTrunkHold.Text)?null:int.Parse(dmrTrunkHold.Text,CultureInfo.InvariantCulture);if(hold is <=0 or >16777215)throw new IOException("Hold TG must be positive or blank.");double hang=double.Parse(dmrTrunkHang.Text,CultureInfo.InvariantCulture),maximum=double.Parse(dmrTrunkMaximum.Text,CultureInfo.InvariantCulture);if(!double.IsFinite(hang)||hang<1||hang>15||!double.IsFinite(maximum)||maximum<5||maximum>300)throw new IOException("Hang must be 1-15 s and maximum 5-300 s.");lock(dmrTrunkRadio.Sync){var m=dmrTrunkRadio.Model;m.RequireConfirmations=dmrTrunkConfirm.IsChecked==true;m.Allowed=allow;m.Ignored=ignore;m.Hold=hold;m.HangSeconds=hang;m.MaximumSeconds=maximum;if(m.Active is {} c&&(ignore.Contains(c.Talkgroup)||hold.HasValue&&hold!=c.Talkgroup||allow.Count>0&&!allow.Contains(c.Talkgroup)))m.End(DateTimeOffset.UtcNow,"Filter changed");}}
    private void SaveDmrTrunkProfile(){var p=ReadDmrTrunkProfile();TrunkFollower.Validate(p);ApplyDmrTrunkRules();Dictionary<int,string> labels;lock(dmrTrunkRadio.Sync)labels=new(dmrTrunkRadio.Model.Labels);var next=new Dictionary<string,TrunkSaved>(dmrTrunkSaved){[p.Id]=new(p,dmrTrunkAllow.Text,dmrTrunkIgnore.Text,dmrTrunkHold.Text,labels,double.Parse(dmrTrunkHang.Text,CultureInfo.InvariantCulture),double.Parse(dmrTrunkMaximum.Text,CultureInfo.InvariantCulture),dmrTrunkRetune.IsChecked==true,dmrTrunkConfirm.IsChecked==true)};string temp=dmrTrunkSettings+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(next.Values.ToArray(),new JsonSerializerOptions{WriteIndented=true}));File.Move(temp,dmrTrunkSettings,true);dmrTrunkSaved.Clear();foreach(var pair in next)dmrTrunkSaved.Add(pair.Key,pair.Value);dmrTrunkProfiles.ItemsSource=next.Values.Select(v=>v.Profile).ToArray();}
    private void StartDmrTrunk(){if(fleetProfile.Role=="Trunk voice")throw new IOException("This is a dedicated voice receiver. Start following on its control receiver, or change this workspace role to Independent.");if(!rfMode||receiver.IsReplay||receiver.SamplingMode!=0)throw new IOException("Start live quadrature SDR first; replay cannot control hardware.");StopActivity("Trunk following started");StopFolderScan("Trunk following started");var p=ReadDmrTrunkProfile();CheckConcurrentFlow(true,p.ControlHz,p.Protocol=="P25"?16000:12500);if(!new ChannelSettings(p.ControlHz,"NFM",p.Protocol=="P25"?16000:12500).Fits(receiver.AppliedFrequency,receiver.AppliedBandwidth)&&dmrTrunkRetune.IsChecked!=true)throw new IOException("Control/rest is outside capture. Tune closer or explicitly allow hardware retunes.");SaveDmrTrunkProfile();Aviation.Stop("Trunk following started");Television.StopLive("Trunk following started");HdRecordings.StopLive("Trunk following started");P25Packets.VoiceToggle.IsChecked=false;digitalMode.SelectedIndex=0;dmrTrunkGeneration++;dmrTrunkRetuneHz=0;dmrTrunkRadio.Start(p);dmrTrunkRadio.SuppressLocalVoice=fleetProfile.Role=="Trunk control";ApplyDmrTrunkRules();if(new ChannelSettings(p.ControlHz,"NFM",16000).Fits(receiver.AppliedFrequency,receiver.AppliedBandwidth))receiver.SetChannel(new(p.ControlHz,"NFM",16000));engine.RetuneBoundary();}
    private void StopDmrTrunk(bool restore){ReleaseDmrFleetAssignments();long hz;lock(dmrTrunkRadio.Sync)hz=dmrTrunkRadio.Model.ControlHz;bool was=dmrTrunkRadio.Running;dmrTrunkGeneration++;dmrTrunkRadio.Stop();dmrTrunkAudioKey="";dmrTrunkAudioFrequency=0;if(was){engine.RetuneBoundary();if(restore&&rfMode&&!receiver.IsReplay&&hz>0)_=RetuneDmrTrunk(hz,dmrTrunkGeneration,true);}}
    private async Task RetuneDmrTrunk(long hz,long generation,bool returning=false){if(dmrTrunkRetuneBusy)return;dmrTrunkRetuneBusy=true;dmrTrunkRetuneHz=hz;dmrTrunkRetuneAt=DateTimeOffset.UtcNow;try{if(!rfMode||receiver.IsReplay)return;var ch=new ChannelSettings(hz,"NFM",16000);if(ch.Fits(receiver.AppliedFrequency,receiver.AppliedBandwidth)){if(returning)receiver.SetChannel(ch);return;}if(trunkRadio.Running)throw new IOException("Automatic retune would interrupt the other protocol flow; use another control receiver.");await receiver.Retune(hz,ch);}catch(Exception ex){if(generation==dmrTrunkGeneration){dmrTrunkRadio.Stop("Retune failed: "+ex.Message);Log("Trunk retune: "+ex.Message);}}finally{dmrTrunkRetuneBusy=false;}}
    private void SkipDmrTrunkCall(){if(dmrFleetOwner is {} owner&&dmrTrunkRadio.Model.Active is {} assigned){lock(owner.dmrTrunkRadio.Sync)owner.dmrTrunkRadio.Model.SkipGroup(assigned.Talkgroup,DateTimeOffset.UtcNow);EndDmrFleetVoice("Skipped by user");}else lock(dmrTrunkRadio.Sync)dmrTrunkRadio.Model.Skip(DateTimeOffset.UtcNow);}
    private void IgnoreDmrTrunkCall(){if(dmrFleetOwner is {} owner&&dmrTrunkRadio.Model.Active is {} assigned){owner.dmrTrunkIgnore.Text=string.Join(',',CommercialParseGroups(owner.dmrTrunkIgnore.Text).Append(assigned.Talkgroup).Distinct());owner.ApplyDmrTrunkRules();EndDmrFleetVoice("Talkgroup ignored on control receiver");return;}lock(dmrTrunkRadio.Sync){if(dmrTrunkRadio.Model.Active is {} c){dmrTrunkIgnore.Text=string.Join(',',CommercialParseGroups(dmrTrunkIgnore.Text).Append(c.Talkgroup).Distinct());ApplyDmrTrunkRules();dmrTrunkRadio.Model.End(DateTimeOffset.UtcNow,"Talkgroup ignored");}}}
    private static string CommercialDmrChannelTag(TrunkCall call)=>call.Protocol=="P25"?"":$" · slot {call.Slot}"+(call.ColorCode is int cc?$" · CC {cc}":"");
    private void AppendDmrTrunkHistory(TrunkEvent row,bool session=false)
    {
        int index=0;while(index<dmrTrunkDiscoveries.Count&&dmrTrunkDiscoveries[index].Time>row.Time)index++;
        dmrTrunkDiscoveries.Insert(index,row);
        while(dmrTrunkDiscoveries.Count>500)dmrTrunkDiscoveries.RemoveAt(dmrTrunkDiscoveries.Count-1);
        if(session)Log($"Trunk {row.Kind}: {row.Receiver} ← {row.Control} · {row.Protocol} TG {row.Talkgroup} {row.Label} · {row.Frequency} MHz{(row.SlotDisplay.Length>0?$" · slot {row.SlotDisplay}":"")}{(row.ColorCodeDisplay.Length>0?$" · CC {row.ColorCodeDisplay}":"")} · radio {row.Radio?.ToString()??"unknown"} · NAC {(row.NacDisplay.Length>0?row.NacDisplay:"unknown")} · {row.Detail}");
    }
    private void TickDmrTrunk()
    {
        foreach(var packet in dmrTrunkRadio.DrainAudio()){if(!dmrFleetAudioReported&&dmrFleetOwner is {} audioOwner&&dmrFleetCall is {} audioCall){dmrFleetAudioReported=true;RecordDmrFleetEvent(audioOwner,audioCall with{Radio=packet.Radio??audioCall.Radio,ColorCode=packet.ColorCode??audioCall.ColorCode},"Decoded audio","Matching decoded voice delivered to listening output");}if(dmrTrunkAudioKey!=packet.Key){dmrTrunkAudioKey=packet.Key;dmrTrunkAudioFrequency=packet.Hz;engine.RetuneBoundary();}engine.FeedStereo(VoiceAudioGain.Apply(packet.Pcm,packet.Protocol=="P25"?voiceGainDb:digitalGainDb),true);}dmrTrunkRadio.Tick();
        foreach(var p in dmrTrunkRadio.DrainObservations()){P25Packets.Add(p);P25Systems.Observe(p);P25Activity.Observe(p);siteCollector?.Observe(p);}
        foreach(var r in dmrTrunkRadio.DrainDmr())ObserveDmrForSaving(r);
        foreach(var e in dmrTrunkRadio.DrainDiscovery())AppendDmrTrunkHistory(e);
        TrunkCall? call;long control;bool running;TrunkEvent[] events;string state,voice;lock(dmrTrunkRadio.Sync){var m=dmrTrunkRadio.Model;call=m.Active;control=m.ControlHz;running=m.Running;state=m.Status;voice=dmrTrunkRadio.VoiceStatus;events=m.Events.ToArray();m.Events.Clear();}
        foreach(var e in events){var row=e with{Receiver=fleetProfile.Name,Control=dmrFleetOwner?.fleetProfile.Name??"",Label=e.Talkgroup is int tg?dmrTrunkRadio.Model.Labels.GetValueOrDefault(tg,""):"",Radio=e.Radio??(e.Talkgroup==dmrFleetCall?.Talkgroup?dmrFleetCall?.Radio:null),Nac=e.Nac??(e.Talkgroup==dmrFleetCall?.Talkgroup?dmrFleetCall?.Nac:null)};AppendDmrTrunkHistory(row,e.Kind=="Call end");if(e.Kind=="Call end"&&dmrFleetOwner is {} owner)owner.AppendDmrTrunkHistory(row,true);}
        string key=call==null?"":$"{call.Protocol}:{call.Hz}:{call.Slot}:{call.Talkgroup}:{call.First.UtcTicks}";if(call==null&&dmrTrunkAudioKey.Length>0){dmrTrunkAudioKey="";dmrTrunkAudioFrequency=control;engine.RetuneBoundary();}
